        JSONArray history=store.entries(BrowserMediaRepositoryRules.PREFIX+"history:");JSONObject firstHistory=history.getJSONObject(0).getJSONObject("value");yes(firstHistory.has("before")&&firstHistory.isNull("before")&&firstHistory.getString("before").equals("null")&&firstHistory.optString("before").equals("null")&&firstHistory.optString("before","qa_fallback").equals("null"));yes(!firstHistory.has("qa_missing")&&firstHistory.optString("qa_missing").isEmpty()&&firstHistory.optString("qa_missing","qa_fallback").equals("qa_fallback"));
        String existing=saved.getString("record_hash");rules.prepareRecordWrite("qa_android_null_delete",key,existing);store.outerTransaction=true;yes(rules.writeRecord("qa_android_null_delete",key,existing,null).getBoolean("cleanup_pending"));yes(new File(media,written.getString("sha256")+".blob").isFile()&&rules.status().getJSONArray("pending_cleanups").length()==1);store.outerTransaction=false;yes(rules.cleanupDeletedKey(key,"qa_android_null_delete").getBoolean("cleanup_complete"));yes(rules.readRecord(key).isNull("record")&&rules.inspectCaptured().getInt("blob_count")==1&&!new File(media,written.getString("sha256")+".blob").exists());
