        File media=new File(root,"shared-files/browser-media");BrowserMediaFiles files=new BrowserMediaFiles(media,new File(root,"shared-uploads"));Memory store=new Memory();BrowserMediaRepositoryRules rules=new BrowserMediaRepositoryRules(store,media);JSONObject ref=upload(files,"shared",200),graph=graph(ref,"QA shared original");rules.beginMirror("qa_shared_begin","active");rules.writeMirrorRecord("qa_shared_a","active","selected",graph);rules.writeMirrorRecord("qa_shared_b","active","customer-draft:qa_shared",graph);rules.completeMirror("qa_shared_complete","active",new JSONArray().put("selected").put("customer-draft:qa_shared"));String hash=rules.readRecord("selected").getString("record_hash");rules.prepareRecordWrite("qa_discard_shared_first","selected",hash);rules.writeRecord("qa_discard_shared_first","selected",hash,null);yes(new File(media,ref.getString("sha256")+".blob").exists()&&rules.inspectCaptured().getInt("blob_count")==1);
